(* [comment removed for export] *)
Lemma mgrow_creditN cr0 cr P0 s s' st :
  PMSP.credit_keep cr0 cr P0 (PNRN.pot_run L s st) -> PQM.p_sk s' = PQM.p_sk s + 1 -> PQM.p_tb s' = PQM.p_tb s -> PQM.p_tg s' = PQM.p_tg s ->
  PQM.p_bb s' = PQM.p_bb s -> PQM.p_bg s' = PQM.p_bg s -> 0 <= PQM.p_sk s ->
  PMSP.credit_keep cr0 (debit L cr (24 * 2 ^ (PQM.p_sk s + 1))) P0 (PNRN.pot_run L s' st).
Proof.
