Lemma cm_frz M1 M2 (P : Z -> Prop) : cm M1 -> mem_grows M1 M2 ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ P i -> M2 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)) ->
  (forall a, P a -> (sp - 30720 <= a < sp) \/ PMK.inW (PNRN.W_mrun AD AQ AE fb) a
                   \/ (a < hl_ceil L /\ (a < hl_img_lo L \/ hl_img_hi L <= a) /\ ~ in_block LBX a)) ->
