Definition gfacts (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool) (len : Z) : Prop :=
  (e = true -> e1 = true) /\ PMSP.src_step (PQM.p_src s) (PQM.p_src s1) sm sm1 /\ PQR.minv_d 1 s1 /\ PQM.p_stk s1 = PQM.p_stk s
  /\ PQM.mgrow_ok s1 /\ Z.of_nat (length (PQM.p_stk s)) <= PQM.MAX_DEPTH /\ Z.of_nat (length (PQM.p_stk s1)) = 2 ^ PQM.p_sk s1
  /\ 0 <= PQM.p_sk s1 <= 10 /\ gcls s1 sm1 len.

