(* [comment removed for export] *)
Lemma GROW_NEW (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool)
      (cr1 : credit) (len : Z) :
  getr R1 (PMK.reg 1) = Z_to_bv 64 0x453d0 -> getr R1 (PMK.reg 10) = Z_to_bv 64 (PQM.PSZ * 2 ^ (PQM.p_sk s1 + 1)) ->
  getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 128) -> getr R1 (PMK.reg 8) = Z_to_bv 64 (2 ^ (PQM.p_sk s1 + 1)) ->
  getr R1 (PMK.reg 9) = Z_to_bv 64 oec -> getr R1 (PMK.reg 18) = Z_to_bv 64 oa -> getr R1 (PMK.reg 19) = Z_to_bv 64 len ->
  getr R1 (PMK.reg 20) = Z_to_bv 64 (24 * 2 ^ PQM.p_sk s1) -> 0 <= len < 2 ^ 64 ->
  (forall x, In x [3; 4; 23; 24; 25; 26; 27]%nat -> getr R1 (PMK.reg x) = getr R (PMK.reg x)) ->
  L5.u64_at RSEGS M1 (sp - 120) 0x46558 -> L5.u64_at RSEGS M1 (sp - 128) op ->
  PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M1 op ois s1 ->
  ae_at M1 oa ov osk st -> others M1 sm1 e1 -> gfacts s1 sm1 e1 len ->
  saved M1 -> cm M1 -> PMSP.credit_keep cr cr1 (PNRN.pot_run L s st) (PNRN.pot_run L s1 st) ->
  model_but_vm model model1 -> hi_heap HI (PNRN.mown s1 st ++ LBX) cr1 M1 (m_vmmaps model1) ->
  PMS.opnew_spec L HI -> PMS.opdel_spec L HI -> PNV.v_begin_object_spec RSEGS AD AQ AE L HI ->
