Lemma GS_POST (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool)
      (cr1 : credit) (len : Z) (fx2 : FPState) (R2 : bvmap 5 word) (M2 : word -> option byte) :
  getr R1 (PMK.reg 9) = Z_to_bv 64 oec -> getr R1 (PMK.reg 18) = Z_to_bv 64 oa ->
  gsok M1 s1 sm1 e1 len -> Z.of_nat (length (PQM.p_stk s)) <= PQM.MAX_DEPTH -> Z.of_nat (length (PQM.p_stk s1)) = 2 ^ PQM.p_sk s1 ->
  0 <= PQM.p_sk s1 <= 10 -> 0 <= len < 2 ^ 64 ->
  (forall x, In x [3; 4; 23; 24; 25; 26; 27]%nat -> getr R1 (PMK.reg x) = getr R (PMK.reg x)) ->
  saved M1 -> cm M1 -> PMSP.credit_keep cr cr1 (PNRN.pot_run L s st) (PNRN.pot_run L s1 st) ->
  model_but_vm model model1 -> hi_heap HI (PNRN.mown s1 st ++ LBX) cr1 M1 (m_vmmaps model1) ->
  PMS.opnew_spec L HI -> PMS.opdel_spec L HI -> PNV.v_begin_object_spec RSEGS AD AQ AE L HI ->
  msteps RSEGS (@mkst fx1 R1 (Z_to_bv 64 0x464c8) M1 (seg_rom RSEGS)) (@mkst fx2 R2 (Z_to_bv 64 0xbe8b0) M2 (seg_rom RSEGS)) -> mem_grows M1 M2 ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 112 <= i < sp - 112 + 112) -> ~ (sp - 128 <= i < sp - 128 + 16) -> M2 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)) ->
  (forall x, In x [3; 4; 9; 18; 23; 24; 25; 26; 27]%nat -> getr R2 (PMK.reg x) = getr R1 (PMK.reg x)) ->
  getr R2 (PMK.reg 1) = Z_to_bv 64 0x453d0 -> getr R2 (PMK.reg 2) = Z_to_bv 64 (sp - 128) ->
  getr R2 (PMK.reg 8) = Z_to_bv 64 (2 ^ (PQM.p_sk s1 + 1)) -> getr R2 (PMK.reg 10) = Z_to_bv 64 (48 * 2 ^ PQM.p_sk s1) ->
  getr R2 (PMK.reg 19) = Z_to_bv 64 len -> getr R2 (PMK.reg 20) = Z_to_bv 64 (24 * 2 ^ PQM.p_sk s1) ->
  L5.u64_at RSEGS M2 (sp - 128) (fb + 32) -> L5.u64_at RSEGS M2 (sp - 120) 288088 -> saved M2 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x464c8 M1 model1) K.
