(* [comment removed for export] *)
Local Ltac gs_case conc Hk0 fx1 R1 M1 model1 s1 sm1 e1 cr1 len V8 V16 X9 X18 GS HL FULL Hlen XS SV1 CM1 CK1 MB1 HH1 OPN OPD VBA :=
  let V8k := fresh "V8k" in let V16k := fresh "V16k" in
  pose proof V8 as V8k; pose proof V16 as V16k; rewrite Hk0 in V8k, V16k;
  let P := fresh "P" in
  pose proof (LF2CBN( conc fx1 R1 M1 (fun j => match j with 2%nat => sp | 34%nat => PQM.p_sb s1 | 36%nat => fb + 32 | 37%nat => fb + 432 | 38%nat => fb + 8
               | 40%nat => bv_unsigned (getr R (PMK.reg 1)) | 41%nat => bv_unsigned (getr R (PMK.reg 8)) | 42%nat => bv_unsigned (getr R (PMK.reg 9))
               | 43%nat => bv_unsigned (getr R (PMK.reg 18)) | 44%nat => bv_unsigned (getr R (PMK.reg 19)) | 45%nat => bv_unsigned (getr R (PMK.reg 20))
               | 46%nat => bv_unsigned (getr R (PMK.reg 21)) | 47%nat => bv_unsigned (getr R (PMK.reg 22)) | 48%nat => len | _ => 0 end) )) as P;
  PMK.feed P ltac:(bafeed);
  let fx2 := fresh "fx2" in let R2 := fresh "R2" in let M2 := fresh "M2" in
  let MG2 := fresh "MG2" in let FRZ2 := fresh "FRZ2" in let MS2 := fresh "MS2" in let KS2 := fresh "KS2" in
  let T1 := fresh "T1" in let T2 := fresh "T2" in let T8 := fresh "T8" in let T10 := fresh "T10" in let T19 := fresh "T19" in let T20 := fresh "T20" in
  let C128 := fresh "C128" in let C120 := fresh "C120" in
  let Q8 := fresh "Q8" in let Q16 := fresh "Q16" in let Q24 := fresh "Q24" in let Q32 := fresh "Q32" in
  let Q40 := fresh "Q40" in let Q48 := fresh "Q48" in let Q56 := fresh "Q56" in let Q64 := fresh "Q64" in
  destruct P as (fx2 & R2 & M2 & MG2 & _ & FRZ2 & MS2 & KS2 & T1 & T2 & T8 & T10 & _ & _ & _ & _ & _ & T19 & T20 & _ & C128 & C120 & _
                 & Q8 & Q16 & Q24 & Q32 & Q40 & Q48 & Q56 & Q64);
  apply (GS_POST fx1 R1 M1 model1 s1 sm1 e1 cr1 len fx2 R2 M2 X9 X18 GS HL FULL ltac:(lia) Hlen XS SV1 CM1 CK1 MB1 HH1 OPN OPD VBA MS2 MG2 FRZ2);
  [ intros x Hx; apply KS2; cbn in Hx; repeat (destruct Hx as [<-|Hx]; [PMK.inl|]); destruct Hx
  | exact T1 | exact T2 | rewrite Hk0; exact T8 | rewrite Hk0; exact T10 | exact T19 | rewrite Hk0; exact T20 | exact C128 | exact C120
  | exact (conj Q8 (conj Q16 (conj Q24 (conj Q32 (conj Q40 (conj Q48 (conj Q56 Q64))))))) ].

(* [comment removed for export] *)
Lemma PUSH_GROW (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool)
      (cr1 : credit) (len : Z) :
  getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 112) -> getr R1 (PMK.reg 8) = Z_to_bv 64 op ->
  getr R1 (PMK.reg 9) = Z_to_bv 64 oec -> getr R1 (PMK.reg 18) = Z_to_bv 64 oa -> getr R1 (PMK.reg 10) = Z_to_bv 64 len -> 0 <= len < 2 ^ 64 ->
  (forall x, In x [3; 4; 23; 24; 25; 26; 27]%nat -> getr R1 (PMK.reg x) = getr R (PMK.reg x)) ->
  gsok M1 s1 sm1 e1 len -> Z.of_nat (length (PQM.p_stk s)) <= PQM.MAX_DEPTH -> Z.of_nat (length (PQM.p_stk s1)) = 2 ^ PQM.p_sk s1 ->
  saved M1 -> cm M1 -> PMSP.credit_keep cr cr1 (PNRN.pot_run L s st) (PNRN.pot_run L s1 st) ->
  model_but_vm model model1 -> hi_heap HI (PNRN.mown s1 st ++ LBX) cr1 M1 (m_vmmaps model1) ->
  PMS.opnew_spec L HI -> PMS.opdel_spec L HI -> PNV.v_begin_object_spec RSEGS AD AQ AE L HI ->
