Lemma ZP (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) :
  getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 112) -> getr R1 (PMK.reg 8) = Z_to_bv 64 op ->
  getr R1 (PMK.reg 9) = Z_to_bv 64 oec -> getr R1 (PMK.reg 18) = Z_to_bv 64 oa ->
  (forall x, In x [3; 4; 19; 20; 21; 22; 23; 24; 25; 26; 27]%nat -> getr R1 (PMK.reg x) = getr R (PMK.reg x)) ->
  PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M1 op ois (sdep s 1025) ->
  ae_at M1 oa ov osk st ->
  PM.iss_at RSEGS AD PMSP.T3 M1 ois str sm -> L5.u64_at RSEGS M1 (op + 496) oa ->
  PMST.base_ok RSEGS AD M1 -> PQST.err_ok RSEGS AD AQ M1 true -> PMSP.ec_at RSEGS M1 oec 8 (pa_errcat_obj AD) ->
  saved M1 -> cm M1 -> hi_heap HI (PNRN.mown s st ++ LBX) cr M1 (m_vmmaps model) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x46630 M1 model) K.
