Lemma lb_run (fx : FPState) R M (pc : Z) (W : bv 32) (rd rs : bv 5) (imm : bv 12) (a0 : Z) :
  fetch_word RSEGS (Z_to_bv 64 pc) = Some W -> is_ecall W = false -> decode_any W = Some (Load SZ1 true rd rs imm, 4%Z) ->
  rd <> 0%bv -> 0 <= pc -> pc + 4 < 2 ^ 64 ->
  getr R rs = Z_to_bv 64 a0 -> 0 <= a0 < 2 ^ 64 -> 0 <= a0 + bv_signed imm < 2 ^ 64 -> L5.defined M (a0 + bv_signed imm) 1 ->
  exists x v, -128 <= x < 128 /\ v = x mod 2 ^ 64 /\ 0 <= v < 2 ^ 64 /\ PNV.sval v = x
    /\ msteps RSEGS (mst fx R pc M) (mst fx (regupd R rd (Z_to_bv 64 v)) (pc + 4) M).
Proof.
