(* [comment removed for export] *)
Lemma srli48_run (fx : FPState) R M (pc : Z) (W : bv 32) (rd rs : bv 5) :
  fetch_word RSEGS (Z_to_bv 64 pc) = Some W -> is_ecall W = false -> decode_any W = Some (ShiftImm ALU_SRL rd rs 48, 4%Z) ->
  rd <> 0%bv -> 0 <= pc -> pc + 4 < 2 ^ 64 ->
